<template>
  <TopicDetailPage v-if="selectedTopicId&&selectedTopicSource==='openalex'" :public-id="selectedTopicId" @back="selectedTopicId=''" />
  <CommunityTopicDetailPage v-else-if="selectedTopicId" :public-id="selectedTopicId" @back="selectedTopicId=''" />
  <section v-else class="square-page" aria-label="研究图谱">
    <header class="square-hero"><div><h1>研究图谱</h1></div><button @click="refresh" :disabled="loading">{{ loading?'刷新中…':'刷新数据' }}</button></header>
    <div class="mode-switch"><label>图谱类型<select v-model="dataSource" @change="switchDataSource"><option value="local">研究图谱</option><option value="openalex">真实学术图谱</option></select></label></div>
    <p v-if="error" class="error">{{ error }}</p>
    <div class="stat-grid"><article v-for="item in statCards" :key="item.label"><b>{{ item.value }}</b><span>{{ item.label }}</span></article></div>
    <div class="dashboard-grid">
      <article class="card hot-card"><header><h2>{{ dataSource==='openalex'?'真实学术主题':'我的常见关键词' }}</h2><small>{{ dataSource==='local'?'来自已导入研究':'来自已导入 OpenAlex 论文' }}</small></header><div v-if="activeHotTopics.length" class="bars"><div v-for="(item,index) in activeHotTopics.slice(0,10)" :key="item.public_id" class="bar-row"><span class="rank">{{ index+1 }}</span><span class="bar-name" :title="item.name">{{ item.name }}</span><span class="bar-track"><i :style="{width:barWidth(item.heat),background:heatColor(item.heat)}"></i></span><strong>{{ item.research_count }}</strong></div></div><p v-else class="empty">暂无关键词，请先从研究结果页导入记录。</p></article>
      <article class="card graph-card"><header><div><h2>{{ dataSource==='openalex'?'真实学术图谱':'研究图谱' }}</h2><small>{{ dataSource==='openalex'?'涵盖 OpenAlex 主题与论文证据研究方向；搜索节点可查看相关研究网络':'节点来自我的研究输入；颜色由研究次数和平均发起时间共同决定，灰色较早、红色较新且活跃' }}</small></div></header><GraphExplorer :data="graph" :data-source="dataSource" @select="handleGraphSelect"/></article>
    </div>
    <div class="lower-grid">
      <article class="card research-list"><header><h2>{{ dataSource==='openalex'?'OpenAlex 真实论文':'我的导入记录' }}</h2><small>共 {{ dataSource==='openalex'?openalexWorks.total:researches.total }} 条</small></header>
        <form v-if="dataSource==='openalex'" class="paper-filters" @submit.prevent="search"><PaperSearchInput v-model="query" @search="search"/><button>搜索</button><select v-model="paperSort" aria-label="真实论文排序" @change="search"><option value="citations">引用量降序</option><option value="citations_asc">引用量升序</option><option value="latest">时间降序</option><option value="oldest">时间升序</option></select></form>
        <div v-if="dataSource==='local'&&researches.items.length" class="research-items"><section v-for="item in researches.items" :key="item.public_id" :class="{pinned:item.is_pinned,failed:item.extraction_status==='failed'}"><div class="research-heading"><div><span class="origin-pill">{{ item.data_origin==='sample'?'样例数据':'我的研究' }}</span><span v-if="item.is_pinned" class="pin-pill">已置顶</span><span v-if="item.extraction_status==='failed'" class="failed-pill">导入失败，请重试</span><button v-if="item.data_origin==='user'" type="button" class="history-title" title="打开对应研究历史" @click="openHistory(item.source_run_id)">{{ item.research_input||item.title }}</button><h3 v-else>{{ item.research_input||item.title }}</h3></div></div><div class="topic-pills"><span v-for="topic in item.topics" :key="topic">{{ topic }}</span><span v-if="item.extraction_status==='pending'">关键词处理中</span><span v-if="item.extraction_status==='failed'" class="extraction-error">没有生成图谱关键词</span></div><footer><span>导入于 {{ formatDate(item.published_at) }}</span><span class="item-actions"><button v-if="item.data_origin==='user'&&item.extraction_status==='failed'" class="retry-button" :disabled="retryingId===item.public_id" @click="retryImport(item)">{{ retryingId===item.public_id?'重新排队中…':'重新提取关键词' }}</button><button class="pin-button" @click="setPinned(item,!item.is_pinned)">{{ item.is_pinned?'取消置顶':'置顶' }}</button><button class="remove-button" @click="removeImport(item)">取消导入</button></span></footer></section><nav v-if="totalPages>1" class="pagination"><button :disabled="page===1" @click="goPage(page-1)">上一页</button><button v-for="number in pageNumbers" :key="number" :class="{active:page===number}" @click="goPage(number)">{{ number }}</button><button :disabled="page===totalPages" @click="goPage(page+1)">下一页</button></nav></div>
        <div v-else-if="dataSource==='openalex'&&openalexWorks.items.length" class="research-items openalex-items"><section v-for="item in openalexWorks.items" :key="item.openalex_id"><div class="research-heading"><div><span class="origin-pill">{{ item.primary_topic||'未分类' }}</span><h3>{{ item.title }}</h3></div><strong>引用 {{ item.cited_by_count }}</strong></div><p>{{ item.abstract||'暂无摘要' }}</p><footer><span>{{ item.authors.slice(0,3).map(x=>x.name).join('、')||'作者未知' }} · {{ item.publication_date||'日期未知' }}</span><a v-if="item.landing_page_url" :href="item.landing_page_url" target="_blank" rel="noopener">查看来源</a></footer></section><nav v-if="totalPages>1" class="pagination"><button :disabled="page===1" @click="goPage(page-1)">上一页</button><span>第 {{ page }} / {{ totalPages }} 页</span><button :disabled="page===totalPages" @click="goPage(page+1)">下一页</button></nav></div><p v-else class="empty">没有匹配的记录。</p>
      </article>
      <ResearchGapAssistant :key="dataSource" :academic="dataSource==='openalex'" :model-profile-id="modelProfileId" @topic="openAcademicTopic" />
    </div>
  </section>
</template>

<script setup lang="ts">
import ResearchGapAssistant from './ResearchGapAssistant.vue';
import GraphExplorer from './GraphExplorer.vue';
import PaperSearchInput from './PaperSearchInput.vue';
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {api} from '../../services/api';import CommunityTopicDetailPage from './CommunityTopicDetailPage.vue';import TopicDetailPage from './TopicDetailPage.vue';import TopicGraph,{type TopicGraphData,type TopicGraphNode} from './TopicGraph.vue';
interface Topic{public_id:string;name:string;research_count:number;heat:number}interface Overview{stats:{researches:number;authors:number;views:number;likes:number};hot_topics:Topic[]}interface OpenAlexOverview{stats:{works:number;topics:number;citations:number;open_access:number};hot_topics:Array<Topic&{citations:number}>}interface PublicResearch{public_id:string;source_run_id:string;title:string;research_input:string;data_origin:'user'|'sample';extraction_status:string;extraction_error?:string;published_at:string;is_pinned:boolean;topics:string[]}interface ResearchList{items:PublicResearch[];total:number;limit:number;offset:number}interface OpenAlexWork{openalex_id:string;title:string;abstract?:string;publication_date?:string;cited_by_count:number;landing_page_url?:string;authors:Array<{name:string}>;primary_topic?:string}interface OpenAlexList{items:OpenAlexWork[];total:number;limit:number;offset:number}interface EnrichmentStatus{works:number;topics:number;enriched_topics:number;topic_needs_review:number;work_needs_review:number}interface QueueStatus{counts:{queued:number;processing:number;completed:number;failed:number;cancelled:number};max_queued:number}
const openalexExamples=['最近一年真实论文数量最多的研究主题有哪些？','与“多模态机器学习应用”共同出现最多的主题有哪些？','“医学教育创新”近90天的论文发表趋势怎样？','比较“医疗人工智能”和“计算药物发现方法”的研究数量','数据库领域最近有哪些真实论文？','概括近一年医学领域的真实研究热点'];
const props=defineProps<{modelProfileId?:string}>();const dataSource=ref<'local'|'openalex'>('local');const query=ref('');const paperSort=ref('citations');const page=ref(1);const pageSize=5;const loading=ref(false);const error=ref('');const question=ref('');const chatting=ref(false);const retryingId=ref('');const selectedTopicId=ref('');const selectedTopicSource=ref<'local'|'openalex'>('local');const overview=ref<Overview>({stats:{researches:0,authors:0,views:0,likes:0},hot_topics:[]});const researches=ref<ResearchList>({items:[],total:0,limit:pageSize,offset:0});const graph=ref<TopicGraphData>({nodes:[],edges:[]});const openalexOverview=ref<OpenAlexOverview>({stats:{works:0,topics:0,citations:0,open_access:0},hot_topics:[]});const openalexWorks=ref<OpenAlexList>({items:[],total:0,limit:20,offset:0});const enrichmentStatus=ref<EnrichmentStatus>({works:0,topics:0,enriched_topics:0,topic_needs_review:0,work_needs_review:0});const queue=ref<QueueStatus>({counts:{queued:0,processing:0,completed:0,failed:0,cancelled:0},max_queued:10});const messages=ref<Array<{role:'user'|'assistant';content:string;plan?:unknown}>>([]);let timer:number|undefined;let queueSignature='';
const activeHotTopics=computed(()=>dataSource.value==='openalex'?openalexOverview.value.hot_topics:overview.value.hot_topics);const statCards=computed(()=>dataSource.value==='openalex'?[{label:'真实论文',value:openalexOverview.value.stats.works},{label:'涉及主题',value:openalexOverview.value.stats.topics},{label:'累计引用',value:openalexOverview.value.stats.citations},{label:'开放获取',value:openalexOverview.value.stats.open_access}]:[{label:'已导入研究',value:researches.value.total},{label:'图谱关键词',value:graph.value.nodes.length},{label:'等待导入',value:queue.value.counts.queued},{label:'正在处理',value:queue.value.counts.processing}]);const maxHeat=computed(()=>Math.max(1,...activeHotTopics.value.map(x=>x.heat)));const minHeat=computed(()=>Math.min(...activeHotTopics.value.map(x=>x.heat),maxHeat.value));const totalPages=computed(()=>Math.max(1,Math.ceil((dataSource.value==='openalex'?openalexWorks.value.total:researches.value.total)/pageSize)));const pageNumbers=computed(()=>Array.from({length:totalPages.value},(_,i)=>i+1));
function barWidth(heat:number){return`${Math.max(4,heat/maxHeat.value*100)}%`}function heatColor(heat:number){const span=maxHeat.value-minHeat.value,ratio=span>0?(heat-minHeat.value)/span:.5;return`hsl(${215-ratio*205} 75% 61%)`}function formatDate(value:string){return new Date(value).toLocaleString('zh-CN')}
function openHistory(sourceRunId:string){if(!sourceRunId)return;window.history.pushState(null,'',`#research/${sourceRunId}`);window.dispatchEvent(new PopStateEvent('popstate'))}
let listVersion=0;
async function loadResearches(){const version=++listVersion;const source=dataSource.value;try{if(source==='openalex'){const result=await api<OpenAlexList>(`/research-square/openalex/works?q=${encodeURIComponent(query.value)}&sort=${paperSort.value}&limit=${pageSize}&offset=${(page.value-1)*pageSize}`);if(version===listVersion && source===dataSource.value)openalexWorks.value=result;}else{const result=await api<ResearchList>(`/research-square/researches?q=${encodeURIComponent(query.value)}&sort=latest&limit=${pageSize}&offset=${(page.value-1)*pageSize}&viewer=local-user`);if(version===listVersion && source===dataSource.value)researches.value=result;}}catch(e){if(version===listVersion)error.value=e instanceof Error?e.message:'论文列表加载失败';}}
async function loadQueue(){queue.value=await api<QueueStatus>('/research-square/import-queue')}
async function refresh(){loading.value=true;error.value='';try{if(dataSource.value==='openalex'){[openalexOverview.value,enrichmentStatus.value,graph.value]=await Promise.all([api<OpenAlexOverview>('/research-square/openalex/overview?days=365'),api<EnrichmentStatus>('/research-square/openalex/enrichment-status'),api<TopicGraphData>('/research-square/openalex/graph?days=365&limit=40&max_edges_per_node=3')])}else{[overview.value,graph.value,queue.value]=await Promise.all([api<Overview>('/research-square/overview?days=365'),api<TopicGraphData>('/research-square/graph?days=365&limit=40&max_edges_per_node=3'),api<QueueStatus>('/research-square/import-queue')])}await loadResearches()}catch(e){error.value=e instanceof Error?e.message:'研究图谱加载失败'}finally{loading.value=false}}
function switchDataSource(){query.value='';page.value=1;question.value='';messages.value=[];selectedTopicId.value='';graph.value={nodes:[],edges:[]};void refresh()}function search(){page.value=1;void loadResearches()}function goPage(value:number){page.value=Math.min(totalPages.value,Math.max(1,value));void loadResearches()}async function setPinned(item:PublicResearch,pinned:boolean){try{await api(`/research-square/researches/${item.public_id}/pin`,{method:'POST',body:JSON.stringify({pinned})});await loadResearches()}catch(e){error.value=e instanceof Error?e.message:'置顶操作失败'}}async function retryImport(item:PublicResearch){if(retryingId.value)return;retryingId.value=item.public_id;error.value='';try{await api('/research-square/publish',{method:'POST',body:JSON.stringify({source_run_id:item.source_run_id,model_profile_id:props.modelProfileId||null})});await refresh()}catch(e){error.value=e instanceof Error?e.message:'重新导入失败'}finally{retryingId.value=''}}async function removeImport(item:PublicResearch){if(!window.confirm(`取消导入“${item.title}”？原始研究历史不会删除。`))return;try{await api(`/research-square/researches/${item.public_id}/import`,{method:'DELETE'});if((page.value-1)*pageSize>=researches.value.total-1&&page.value>1)page.value--;await refresh()}catch(e){error.value=e instanceof Error?e.message:'取消导入失败'}}function openAcademicTopic(id:string){selectedTopicSource.value='openalex';selectedTopicId.value=id}function handleGraphSelect(node:TopicGraphNode){selectedTopicSource.value=dataSource.value;selectedTopicId.value=node.id}
async function sendQuestion(){if(!question.value||chatting.value)return;const asked=question.value;messages.value.push({role:'user',content:asked});question.value='';chatting.value=true;try{const result=await api<{answer:string;plan:unknown}>('/research-square/chat',{method:'POST',body:JSON.stringify({question:asked,model_profile_id:props.modelProfileId||null,days:365,domain_slug:null,data_source:dataSource.value})});messages.value.push({role:'assistant',content:result.answer,plan:result.plan})}catch(e){messages.value.push({role:'assistant',content:e instanceof Error?e.message:'分析失败'})}finally{chatting.value=false}}
async function pollQueue(){if(dataSource.value!=='local')return;try{await loadQueue();const next=JSON.stringify(queue.value.counts);if(queueSignature&&next!==queueSignature)await refresh();queueSignature=next}catch{/* 手动刷新时显示错误 */}}onMounted(async()=>{await refresh();queueSignature=JSON.stringify(queue.value.counts);timer=window.setInterval(pollQueue,3000)});onBeforeUnmount(()=>{if(timer)window.clearInterval(timer)});
const emit = defineEmits<{ navigate: [] }>();
watch([selectedTopicId, dataSource], () => emit('navigate'));
</script>

<style scoped>
