ng:12px;border-radius:12px;font-size:13px}.chat-messages .user{background:#eef3ff;margin-left:28px}.chat-messages .assistant{background:#f4f8f6;margin-right:20px}.chat-messages p{white-space:pre-wrap;line-height:1.6;margin:5px 0}.chat-messages pre{white-space:pre-wrap;font-size:10px}.chat-card form{display:flex;flex-direction:column;gap:9px;margin-top:12px}.chat-card button{background:#506bd8;color:#fff}.openalex-items a{color:#4965ca;text-decoration:none;font-weight:700}.empty{color:#8a96aa;text-align:center;padding:35px 10px}.error{background:#fff0f1;color:#b93144;padding:12px 16px;border-radius:10px}@media(max-width:1200px){.square-page{grid-column:2/4}.lower-grid{grid-template-columns:1fr}.stat-grid{grid-template-columns:1fr 1fr}}@media(max-width:760px){.square-page{grid-column:1/-1;padding:16px}.filters{grid-template-columns:1fr}.stat-grid{grid-template-columns:1fr 1fr}}
.history-title{display:block!important;margin:7px 0 0!important;padding:0!important;background:transparent!important;color:#27344e!important;text-align:left;font-size:15px;line-height:1.55}.history-title:hover{color:#4965ca!important;text-decoration:underline}.history-title::after{content:'  ↗';font-size:11px;color:#6d82cf}
